#include <bits/stdc++.h>
using namespace std;

int invnum(const std::vector<int>& sequence) {
    int count = 0;
    int len = sequence.size();
    for (int i = 0; i < len; ++i) {
        for (int j = i + 1; j < len; ++j) {
            if (sequence[i] > sequence[j]) {
                count++;
            }
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;

    // Using unordered_map for memoization: key is k, value is int
    // Since cache depends on N and flag, we can store as a 3D array or map
    // But for simplicity, we can use a map with pair as key
    // But to match the original, we can use a nested vector of unordered_maps
    // cache_memo[N][flag][k]
    // N up to n, flag 0 or 1, k varies
    // Since k can be negative, we need to handle that
    // We'll use a vector of unordered_maps for each N and flag
    vector<vector<unordered_map<int, int>>> cache_memo(2, vector<unordered_map<int, int>>(n + 1));

    function<int(int, int, bool)> solve = [&](int N, int K, bool flag) -> int {
        int flag_idx = flag ? 1 : 0;
        auto& cache = cache_memo[flag_idx][N];
        if (cache.count(K)) {
            return cache[K];
        }
        if (N == 1) {
            int res = 0;
            if (!flag && K < 0) {
                res = 1;
            }
            cache[K] = res;
            return res;
        }
        int max_inv = N * (N - 1) / 2;
        if (K < -max_inv - 1) {
            int res = solve(N, -max_inv - 1, flag);
            cache[K] = res;
            return res;
        }
        if (K >= max_inv) {
            cache[K] = 0;
            return 0;
        }
        int total = 0;
        for (int delta = -N + 1; delta < N; ++delta) {
            if (flag && delta > 0) continue;
            int weight = std::min(N - delta, delta + N);
            total += (long long)solve(N - 1, K - delta, flag && delta == 0) * weight % mod;
            total %= mod;
        }
        cache[K] = total;
        return total;
    };

    int answer = solve(n, 0, true) % mod;
    cout << answer << "\n";

    return 0;
}
